"""
test_summarizer.py
------------------
Tests for agents/summarizer.py

Run from autoresearch/:
    python test_summarizer.py
"""

import sys
sys.path.insert(0, ".")

from unittest.mock import patch
from agents.summarizer import SummarizerAgent
from core.schemas import validate, SummarizerOutput

print("=" * 50)

# Reusable test snippets
SAMPLE_SNIPPETS = [
    {
        "text": (
            "Hallucination in artificial intelligence refers to a confident response "
            "generated by an AI that does not seem to be justified by its training data. "
            "Large language models generate text by predicting the next token based on "
            "statistical patterns, which can lead to plausible-sounding but incorrect output."
        ),
        "url":   "https://en.wikipedia.org/wiki/Hallucination_(artificial_intelligence)",
        "title": "Hallucination (artificial intelligence)",
    },
    {
        "text": (
            "Retrieval-Augmented Generation (RAG) is a technique that reduces hallucination "
            "by grounding the model's responses in retrieved documents. Rather than relying "
            "purely on parametric memory, the model can reference external knowledge at "
            "inference time."
        ),
        "url":   "https://en.wikipedia.org/wiki/Retrieval-augmented_generation",
        "title": "Retrieval-augmented generation",
    },
]

# ── Test 1: Offline — valid mock response passes ──────────────────────────────
print("TEST 1: Offline — valid mock LLM response")

mock_response = {
    "sub_question": "What causes LLM hallucinations?",
    "facts": [
        {
            "claim":      "LLMs hallucinate because they predict tokens statistically, not factually.",
            "source_url": "https://en.wikipedia.org/wiki/Hallucination_(artificial_intelligence)",
            "confidence": "high",
        },
        {
            "claim":      "RAG reduces hallucination by grounding responses in retrieved documents.",
            "source_url": "https://en.wikipedia.org/wiki/Retrieval-augmented_generation",
            "confidence": "high",
        },
        {
            "claim":      "Hallucination produces confident but factually incorrect output.",
            "source_url": "https://en.wikipedia.org/wiki/Hallucination_(artificial_intelligence)",
            "confidence": "medium",
        },
    ],
}

with patch("agents.summarizer.chat_json", return_value=mock_response):
    summarizer = SummarizerAgent()
    result = summarizer.run({
        "sub_question": "What causes LLM hallucinations?",
        "snippets": SAMPLE_SNIPPETS,
    })

validate(SummarizerOutput, result)
assert len(result["facts"]) == 3,                          "FAIL: wrong fact count"
assert result["facts"][0]["confidence"] == "high",         "FAIL: wrong confidence"
assert result["sub_question"] == "What causes LLM hallucinations?", "FAIL: sub_question mismatch"
print("PASS ✓")

# ── Test 2: Offline — empty snippets returns graceful fallback ────────────────
print("\nTEST 2: Offline — empty snippets → graceful 'no data' fact")

summarizer2 = SummarizerAgent()
result2 = summarizer2.run({
    "sub_question": "Some unanswerable question",
    "snippets": [],
})

assert len(result2["facts"]) == 1,               "FAIL: expected exactly 1 fallback fact"
assert result2["facts"][0]["confidence"] == "low", "FAIL: fallback should be low confidence"
assert result2["facts"][0]["source_url"] == "N/A", "FAIL: fallback source_url should be N/A"
print("PASS ✓")

# ── Test 3: Offline — bad confidence value is normalised ─────────────────────
print("\nTEST 3: Offline — invalid confidence value is normalised to 'medium'")

bad_confidence_response = {
    "sub_question": "What causes LLM hallucinations?",
    "facts": [
        {
            "claim":      "Some claim.",
            "source_url": "https://example.com",
            "confidence": "very_high",      # not a valid value
        },
        {
            "claim":      "Another claim.",
            "source_url": "https://example.com",
            "confidence": "high",
        },
        {
            "claim":      "Third claim.",
            "source_url": "https://example.com",
            "confidence": "low",
        },
    ],
}

with patch("agents.summarizer.chat_json", return_value=bad_confidence_response):
    summarizer3 = SummarizerAgent()
    result3 = summarizer3.run({
        "sub_question": "What causes LLM hallucinations?",
        "snippets": SAMPLE_SNIPPETS,
    })

assert result3["facts"][0]["confidence"] == "medium", "FAIL: should have been normalised to medium"
print("PASS ✓")

# ── Test 4: Offline — missing fact key raises ValueError ──────────────────────
print("\nTEST 4: Offline — fact missing 'source_url' raises ValueError")

missing_key_response = {
    "sub_question": "What causes LLM hallucinations?",
    "facts": [
        {
            "claim":      "Some claim.",
            # "source_url" is intentionally missing
            "confidence": "high",
        },
    ],
}

with patch("agents.summarizer.chat_json", return_value=missing_key_response):
    try:
        summarizer4 = SummarizerAgent()
        summarizer4.run({
            "sub_question": "What causes LLM hallucinations?",
            "snippets": SAMPLE_SNIPPETS,
        })
        print("FAIL ✗ — should have raised ValueError")
    except ValueError as e:
        print(f"PASS ✓  (raised ValueError: {e})")

# ── Test 5: Live API ──────────────────────────────────────────────────────────
print("\nTEST 5: Live API — real summarization (needs OPENAI_API_KEY)")
try:
    summarizer5 = SummarizerAgent()
    result5 = summarizer5.run({
        "sub_question": "What causes LLM hallucinations?",
        "snippets": SAMPLE_SNIPPETS,
    })

    print(f"  Facts extracted: {len(result5['facts'])}")
    for i, fact in enumerate(result5["facts"], 1):
        print(f"  [{i}] [{fact['confidence'].upper()}] {fact['claim'][:100]}")

    validate(SummarizerOutput, result5)
    print("PASS ✓")

except RuntimeError as e:
    print(f"SKIP — API unavailable: {e}")

print("\n" + "=" * 50)
print("All Summarizer tests done. Step 5 complete!")